html:
{% set pos = frappe.get_doc("POS Invoice", doc.pos_invoice) %}
{% set company_doc = frappe.get_doc("Company", doc.company) %}
{% set company_address = frappe.get_doc("Address", doc.billing_address) if doc.billing_address else None %}

{# ================= ตั้งค่า (ปรับได้) ================= #}
{% set ROWS_PER_PAGE = 18 %}     {# จำนวนรายการสูงสุดต่อหน้า (หน้าที่ไม่ใช่หน้าสุดท้าย) #}
{% set ROWS_LAST_PAGE = 10 %}    {# จำนวนรายการสูงสุดในหน้าสุดท้าย (ต้องเหลือที่ให้ยอดรวม + ลายเซ็น) #}
{% set SELLER_BRANCH = "สำนักงานใหญ่" %}   {# หรือ "สาขาที่ 00001" #}
{% set COPY_LABEL = "ต้นฉบับ" %}          {# ต้นฉบับ / สำเนา #}
{% set vat_rate = (pos.taxes[0].rate if pos.taxes and pos.taxes[0].rate else 7) %}
{% set seller_tax_id = (company_address.tax_id if company_address and company_address.tax_id else company_doc.tax_id) %}

{# ================= แปลงตัวเลขเป็นคำอ่านภาษาไทย ================= #}
{% macro thai_group(value, has_prefix=false) -%}
    {% set ns = namespace(out="") %}
    {% set words = ["", "หนึ่ง", "สอง", "สาม", "สี่", "ห้า", "หก", "เจ็ด", "แปด", "เก้า"] %}
    {% for unit, label in [(100000,"แสน"),(10000,"หมื่น"),(1000,"พัน"),(100,"ร้อย"),(10,"สิบ"),(1,"")] %}
        {% set digit = (value // unit) % 10 %}
        {% if digit %}
            {% if unit == 10 and digit == 1 %}
                {% set ns.out = ns.out ~ "สิบ" %}
            {% elif unit == 10 and digit == 2 %}
                {% set ns.out = ns.out ~ "ยี่สิบ" %}
            {% elif unit == 1 and digit == 1 and (value > 1 or has_prefix) %}
                {% set ns.out = ns.out ~ "เอ็ด" %}
            {% else %}
                {% set ns.out = ns.out ~ words[digit] ~ label %}
            {% endif %}
        {% endif %}
    {% endfor %}
    {{- ns.out -}}
{%- endmacro %}

{% macro thai_integer(value) -%}
    {% if value == 0 %}ศูนย์{% else %}
    {% if value >= 1000000 %}{{- thai_integer(value // 1000000) -}}ล้าน{% endif %}
    {{- thai_group(value % 1000000, value >= 1000000) -}}
    {% endif %}
{%- endmacro %}

{# ================= แบ่งรายการเป็นหน้า ================= #}
{% set items = pos.items or [] %}
{% set total_items = items | length %}
{% set pg = namespace(pages=[], start=0) %}
{% for _i in range(total_items + 1) %}
    {% set remaining = total_items - pg.start %}
    {% if remaining > 0 %}
        {% if remaining <= ROWS_LAST_PAGE %}
            {% set take = remaining %}
        {% elif remaining > ROWS_PER_PAGE %}
            {% set take = ROWS_PER_PAGE %}
        {% else %}
            {# เหลือมากกว่าที่หน้าสุดท้ายรับได้ แต่ไม่เต็มหน้า -> แบ่งครึ่งให้สมดุล #}
            {% set last_rows = [remaining // 2, ROWS_LAST_PAGE] | min %}
            {% set take = remaining - last_rows %}
        {% endif %}
        {% set pg.pages = pg.pages + [items[pg.start:pg.start + take]] %}
        {% set pg.start = pg.start + take %}
    {% endif %}
{% endfor %}
{% if not pg.pages %}{% set pg.pages = [[]] %}{% endif %}
{% set total_pages = pg.pages | length %}
{% set run = namespace(idx=0, carried=0) %}

<style>
    @page { size: A4; margin: 12mm; }
    body { font-family: Tahoma, Arial, sans-serif; font-size: 13px; color: #333; margin: 0; padding: 0; background: #fff; }

    .tax-page { width: 100%; padding: 5px; box-sizing: border-box; }
    .page-break { page-break-after: always; break-after: page; }

    .header-table, .item-table, .total-table, .sign-table { width: 100%; border-collapse: collapse; }
    .header-table td { vertical-align: top; padding: 5px; }

    .company-logo { width: 90px; max-height: 85px; object-fit: contain; margin-right: 12px; }
    .company-info { line-height: 1.6; }
    .company-info h3 { font-size: 17px; margin: 0 0 5px 0; color: #222; }

    .title-box { text-align: right; line-height: 1.5; }
    .title-box h2 { margin: 0 0 5px 0; font-size: 20px; color: #2c3e50; }
    .title-box p { margin: 2px 0; }
    .english-title { color: #c0392b; font-weight: bold; font-size: 14px; }
    .copy-label { display: inline-block; border: 1px solid #c0392b; color: #c0392b; padding: 1px 8px; font-weight: bold; font-size: 12px; margin-bottom: 4px; }
    .page-no { font-size: 12px; color: #555; }

    .customer-box { border: 1px solid #ccc; padding: 10px 12px; margin: 10px 0; border-radius: 4px; background: #fafafa; line-height: 1.7; }

    .item-table th, .item-table td { border: 1px solid #bdc3c7; padding: 6px 7px; }
    .item-table th { background: #2c3e50; color: #fff; text-align: center; font-weight: bold; }
    .item-table td { vertical-align: top; }
    .item-table tr { page-break-inside: avoid; }
    .carry-row td { background: #f4f6f7; font-weight: bold; }

    .text-right { text-align: right !important; }
    .text-center { text-align: center !important; }
    .small-text { font-size: 11px; color: #555; }

    .continue-note { text-align: right; margin-top: 6px; font-size: 12px; font-style: italic; color: #555; }

    .closing-block { page-break-inside: avoid; break-inside: avoid; }
    .total-table { margin-top: 12px; }
    .total-table td { padding: 5px 6px; vertical-align: top; }
    .grand-total td { font-weight: bold; background: #f1f2f6; border-top: 1px solid #777; border-bottom: 1px solid #777; }
    .source-reference { margin-top: 10px; font-size: 11px; color: #666; }

    .sign-table { margin-top: 35px; }
    .sign-table td { width: 50%; text-align: center; vertical-align: bottom; padding: 0 20px; }
    .signature-line { border-bottom: 1px dotted #333; height: 40px; margin-bottom: 5px; }
    .sign-table p { margin: 3px 0; }
</style>

{% for page_items in pg.pages %}
{% set page_no = loop.index %}
{% set is_first = loop.first %}
{% set is_last = loop.last %}

<div class="tax-page{% if not is_last %} page-break{% endif %}">

    <!-- ===== HEADER (แสดงทุกหน้า) ===== -->
    <table class="header-table">
        <tr>
            <td style="width: 60%;">
                <table>
                    <tr>
                        {% if company_doc.company_logo %}
                        <td style="width: 100px; vertical-align: top;">
                            <img src="{{ frappe.utils.get_url(company_doc.company_logo) }}" class="company-logo">
                        </td>
                        {% endif %}
                        <td class="company-info">
                            <h3>{{ company_doc.company_name or company_doc.name }}</h3>
                            {% if company_address %}
                                {% if company_address.address_line1 %}{{ company_address.address_line1 }}<br>{% endif %}
                                {% if company_address.address_line2 %}{{ company_address.address_line2 }}<br>{% endif %}
                                {{ company_address.city or "" }} {{ company_address.state or "" }}
                                {{ company_address.pincode or "" }} {{ company_address.country or "" }}<br>
                                {% if company_address.phone %}โทรศัพท์: {{ company_address.phone }}<br>{% endif %}
                                {% if company_address.email_id %}อีเมล: {{ company_address.email_id }}<br>{% endif %}
                            {% endif %}
                            <strong>เลขประจำตัวผู้เสียภาษี:</strong> {{ seller_tax_id or "-" }}
                            &nbsp;<strong>{{ SELLER_BRANCH }}</strong>
                        </td>
                    </tr>
                </table>
            </td>
            <td class="title-box" style="width: 40%;">
                <span class="copy-label">{{ COPY_LABEL }}</span>
                <h2>ใบกำกับภาษี / ใบเสร็จรับเงิน</h2>
                <div class="english-title">TAX INVOICE / RECEIPT</div>
                <p><strong>เลขที่:</strong> {{ doc.full_tax_invoice_number or "-" }}</p>
                <p><strong>วันที่:</strong>
                    {{ frappe.utils.formatdate(doc.full_tax_invoice_date, "dd/MM/yyyy") if doc.full_tax_invoice_date else "-" }}
                </p>
                <p class="page-no">หน้า {{ page_no }} / {{ total_pages }}</p>
            </td>
        </tr>
    </table>

    <!-- ===== CUSTOMER (แสดงทุกหน้า) ===== -->
    <div class="customer-box">
        <table style="width: 100%; border-collapse: collapse;">
            <tr>
                <td style="width: 60%; vertical-align: top;">
                    <strong>นามผู้ซื้อ / ลูกค้า:</strong> {{ doc.buyer_name or doc.original_customer_name or "-" }}
                </td>
                <td style="width: 40%; text-align: right; vertical-align: top; white-space: nowrap;">
                    <strong>เลขประจำตัวผู้เสียภาษี:</strong> {{ doc.buyer_tax_id or "-" }}
                </td>
            </tr>
            <tr>
                <td style="vertical-align: top;"><strong>ที่อยู่:</strong> {{ doc.buyer_address or "-" }}</td>
                <td style="text-align: right; vertical-align: top; white-space: nowrap;">
                    {% if doc.buyer_branch %}<strong>สาขา:</strong> {{ doc.buyer_branch }}{% endif %}
                </td>
            </tr>
        </table>
    </div>

    <!-- ===== ITEMS ===== -->
    <table class="item-table">
        <thead>
            <tr>
                <th style="width: 8%;">ลำดับ</th>
                <th style="width: 42%;">รายการสินค้า / บริการ</th>
                <th style="width: 12%;">จำนวน</th>
                <th style="width: 17%;">หน่วยละ</th>
                <th style="width: 21%;">จำนวนเงิน (บาท)</th>
            </tr>
        </thead>
        <tbody>
            {% if not is_first %}
            <tr class="carry-row">
                <td colspan="4" class="text-right">ยอดยกมา</td>
                <td class="text-right">{{ frappe.utils.fmt_money(run.carried, precision=2) }}</td>
            </tr>
            {% endif %}

            {% for item in page_items %}
            {% set run.idx = run.idx + 1 %}
            {% set run.carried = run.carried + (item.amount or 0) %}
            <tr>
                <td class="text-center">{{ run.idx }}</td>
                <td>
                    <strong>{{ item.item_name or item.item_code }}</strong>
                    {% if item.description and item.description != item.item_name %}
                        <br><span class="small-text">{{ item.description }}</span>
                    {% endif %}
                </td>
                <td class="text-center">{{ frappe.utils.fmt_money(item.qty, precision=2) }} {{ item.uom or "" }}</td>
                <td class="text-right">{{ frappe.utils.fmt_money(item.rate, precision=2) }}</td>
                <td class="text-right">{{ frappe.utils.fmt_money(item.amount, precision=2) }}</td>
            </tr>
            {% endfor %}

            {% if not is_last %}
            <tr class="carry-row">
                <td colspan="4" class="text-right">ยอดยกไป</td>
                <td class="text-right">{{ frappe.utils.fmt_money(run.carried, precision=2) }}</td>
            </tr>
            {% endif %}
        </tbody>
    </table>

    {% if not is_last %}
        <div class="continue-note">
            มีต่อหน้าถัดไป ({{ page_no + 1 }}/{{ total_pages }}) — ใบกำกับภาษีเลขที่ {{ doc.full_tax_invoice_number or "-" }}
        </div>
    {% else %}
    <!-- ===== TOTALS + SIGNATURE (เฉพาะหน้าสุดท้าย, ไม่แยกหน้า) ===== -->
    <div class="closing-block">
        <table class="total-table">
            <tr>
                <td style="width: 57%; vertical-align: bottom;">
                    <p><strong>จำนวนเงินรวม (ตัวอักษร):</strong></p>
                    {% set amount_parts = ("%.2f" | format(doc.original_grand_total or 0)).split(".") %}
                    <p>({{ thai_integer(amount_parts[0] | int) }}บาท{% if amount_parts[1] | int == 0 %}ถ้วน{% else %}{{ thai_integer(amount_parts[1] | int) }}สตางค์{% endif %})</p>
                    <p class="source-reference">
                        อ้างอิงใบกำกับภาษีอย่างย่อ / POS Invoice เลขที่: {{ doc.pos_invoice }}
                    </p>
                </td>
                <td style="width: 43%;">
                    <table style="width: 100%; border-collapse: collapse;">
                        <tr>
                            <td>มูลค่าสินค้า/บริการ:</td>
                            <td class="text-right">{{ frappe.utils.fmt_money(doc.original_net_total or 0, precision=2) }}</td>
                            <td>บาท</td>
                        </tr>
                        <tr>
                            <td>ภาษีมูลค่าเพิ่ม {{ vat_rate | int }}%:</td>
                            <td class="text-right">{{ frappe.utils.fmt_money(doc.original_vat_amount or 0, precision=2) }}</td>
                            <td>บาท</td>
                        </tr>
                        <tr class="grand-total">
                            <td>จำนวนเงินรวมทั้งสิ้น:</td>
                            <td class="text-right">{{ frappe.utils.fmt_money(doc.original_grand_total or 0, precision=2) }}</td>
                            <td>บาท</td>
                        </tr>
                    </table>
                </td>
            </tr>
        </table>

        <table class="sign-table">
            <tr>
                <td>
                    <div class="signature-line"></div>
                    <p>ผู้รับสินค้า / Customer</p>
                    <p>วันที่: _____/_____/_____</p>
                </td>
                <td>
                    <div class="signature-line"></div>
                    <p>ผู้มีอำนาจลงนาม / Authorized Signature</p>
                    <p>วันที่: _____/_____/_____</p>
                </td>
            </tr>
        </table>
    </div>
    {% endif %}

</div>
{% endfor %}
